# Agentic Incident Triage Worker Definition
class IncidentAgent:
    def __init__(self, telemetry_tools, runbook_engine):
        self.tools = [telemetry_tools.query_metrics, runbook_engine.execute_remediation]
        self.agent = initialize_agent(self.tools, role="Autonomous SRE Triage")

    async def evaluate_alert(self, alert_context):
        plan = await self.agent.reason_and_act(alert_context)
        return plan.execute_verified_safe_actions()
